/**
 * Phase 4 final two P1 corrections: capability removal bypass (P1-02) and
 * hash-contract-aware legacy versions (P1-05). Legacy fixtures were generated by
 * running commit e696c05's own code (see fixtures/legacy-e696c05-*.json).
 */
import { render, screen } from "@testing-library/react";
import { beforeEach, describe, expect, it } from "vitest";
import { ProposalPreview } from "@/components/proposal/preview";
import { proposalStudio as P } from "@/data/proposal-studio";
import { QUARANTINE_KEY, STORAGE_KEY, memoryBackend, store } from "@/data/store";
import {
  HASH_CONTRACT,
  hashContractOf,
  versionIntegrityProblems,
  type ProposalVersionRecord,
} from "@/domain/proposal";
import issuedFx from "./fixtures/legacy-e696c05-issued.json";
import approvedFx from "./fixtures/legacy-e696c05-approved.json";
import {
  issuedProposal,
  readyProposal,
  resetProposalTestState,
  REVIEWER,
} from "./proposal-fixtures";
import { MGR, PRO } from "./solution-fixtures";

beforeEach(resetProposalTestState);
type Any = any; // eslint-disable-line @typescript-eslint/no-explicit-any
const ackOf = (v: ProposalVersionRecord) => [
  ...v.document.deliverables.filter((d) => d.info.needsQualification).map((d) => d.id),
  ...v.document.risks.filter((x) => x.resolution === "accepted").map((x) => x.id),
];
async function receivablesLine() {
  const r = await readyProposal();
  const lid = await P.upsertChild(PRO, r.p.id, "lines", {
    category: "aurumi_subscription",
    catalogItemId: "app_receivables",
    priceBookItemId: "pb_receivables",
    description: "Receivables app",
  });
  return { ...r, lid };
}
const lineOf = async (pid: string, lid: string) =>
  (await P.get(PRO, pid)).workspace.lines.find((x) => x.id === lid)!;

describe("P1-02 explicit capability removal cannot bypass applicability", () => {
  it("null capability with the general core-user price is rejected and nothing changes", async () => {
    const { p, lid } = await receivablesLine();
    await expect(
      P.upsertChild(PRO, p.id, "lines", {
        id: lid,
        category: "aurumi_subscription",
        catalogItemId: null,
        priceBookItemId: "pb_core_user",
        description: "Receivables app",
      }),
    ).rejects.toThrow(/bound to app_receivables; its capability cannot be removed/);
    const l = await lineOf(p.id, lid);
    expect(l.catalogItemId).toBe("app_receivables");
    expect(l.priceRef?.priceBookItemId).toBe("pb_receivables");
  });
  it("the same bypass is rejected with the price kept, and with an exception attached", async () => {
    const { p, lid } = await receivablesLine();
    for (const extra of [
      { priceBookItemId: "pb_receivables" },
      {
        priceBookItemId: "pb_core_user",
        priceException: { rationale: "General seats", permits: ["applicability" as const] },
      },
    ])
      await expect(
        P.upsertChild(PRO, p.id, "lines", {
          id: lid,
          category: "aurumi_subscription",
          catalogItemId: null,
          description: "Receivables app",
          ...extra,
        }),
      ).rejects.toThrow(/cannot be removed/);
  });
  it("a rejected removal leaves the proposal issuing at the Receivables price", async () => {
    const { p, lid } = await receivablesLine();
    await expect(
      P.upsertChild(PRO, p.id, "lines", {
        id: lid,
        category: "aurumi_subscription",
        catalogItemId: null,
        priceBookItemId: "pb_core_user",
        description: "Receivables app",
      }),
    ).rejects.toThrow();
    const ver = await P.submitForReview(PRO, p.id);
    await P.approve(REVIEWER, p.id, ver.id, { acknowledged: ackOf(ver) });
    const issued = await P.issue(MGR, p.id, ver.id);
    const l = issued.document.commercials.lines.find((x) => x.id === lid)!;
    expect(l).toMatchObject({ catalogItemId: "app_receivables" });
    expect(l.priceRef?.priceBookItemId).toBe("pb_receivables");
    expect(l.computed.basis).not.toBe("price_exception");
  });
  it("omitting the capability on update preserves it", async () => {
    const { p, lid } = await receivablesLine();
    await P.upsertChild(PRO, p.id, "lines", {
      id: lid,
      category: "aurumi_subscription",
      priceBookItemId: "pb_receivables",
      quantity: 2,
      description: "Receivables app",
    });
    expect((await lineOf(p.id, lid)).catalogItemId).toBe("app_receivables");
  });
  it("valid replacement is still checked against the price", async () => {
    const { p, lid, handoff } = await receivablesLine();
    const other = handoff.catalog.items.find((c) => c.id !== "app_receivables")!;
    await expect(
      P.upsertChild(PRO, p.id, "lines", {
        id: lid,
        category: "aurumi_subscription",
        catalogItemId: other.id,
        priceBookItemId: "pb_receivables",
        description: "x",
      }),
    ).rejects.toThrow(new RegExp(`not ${other.id}`));
  });
  it("new general subscriptions are accepted, including with an explicit null", async () => {
    const { p } = await readyProposal();
    const lid = await P.upsertChild(PRO, p.id, "lines", {
      category: "aurumi_subscription",
      catalogItemId: null,
      priceBookItemId: "pb_core_user",
      description: "Workspace users",
    });
    expect((await lineOf(p.id, lid)).catalogItemId).toBeUndefined();
  });
  it("an authorized applicability exception keeps the original capability", async () => {
    const { p, lid } = await receivablesLine();
    await P.upsertChild(PRO, p.id, "lines", {
      id: lid,
      category: "aurumi_subscription",
      priceBookItemId: "pb_core_user",
      description: "Receivables app",
      priceException: { rationale: "Bundled seats", permits: ["applicability"] },
    });
    await P.authorizeCommercial(REVIEWER, p.id, { kind: "exception", itemId: lid });
    const ver = await P.submitForReview(PRO, p.id);
    expect(ver.document.commercials.lines.find((x) => x.id === lid)!.catalogItemId).toBe(
      "app_receivables",
    );
  });
});

describe("P1-05 legacy (e696c05) versions under the hash-contract policy", () => {
  function restore(fx: { envelope: unknown }) {
    const backend = memoryBackend();
    backend.write(STORAGE_KEY, JSON.stringify(fx.envelope));
    store.attach(backend);
    return backend;
  }
  const savedVersion = (fx: Any, id: string) =>
    fx.envelope.tables.proposalVersions.find((v: Any) => v.id === id);
  it("a genuine issued e696c05 version restores without quarantine, unchanged", async () => {
    restore(issuedFx);
    expect(store.persistence().quarantined).toBe(0);
    const v = (await P.get(PRO, issuedFx.proposalId)).versions.find(
      (x) => x.id === issuedFx.versionId,
    )!;
    const orig = savedVersion(issuedFx, issuedFx.versionId);
    expect("hashContract" in orig).toBe(false);
    expect(hashContractOf(v)).toBe("proposal-content-hash/1");
    expect(versionIntegrityProblems(v)).toEqual([]);
    expect(v.contentHash).toBe(orig.contentHash);
    expect(JSON.stringify(v.review)).toBe(JSON.stringify(orig.review));
    expect(JSON.stringify(v.issue)).toBe(JSON.stringify(orig.issue));
    expect(JSON.stringify(v.document)).toBe(JSON.stringify(orig.document));
    expect("hashContract" in store.table("proposalVersions")[0]!).toBe(false);
  });
  it("the legacy issued version can be viewed and printed as history", async () => {
    restore(issuedFx);
    const v = (await P.get(PRO, issuedFx.proposalId)).versions[0]!;
    render(
      <ProposalPreview doc={v.document} label="Historical version" issuedAt={v.issue?.issuedAt} />,
    );
    expect(screen.getByText("Historical version")).toBeTruthy();
    expect(screen.getAllByText(new RegExp(v.document.proposal.title)).length).toBeGreaterThan(0);
  });
  it("a legacy approved version cannot be newly issued; revise and resubmit is the path", async () => {
    restore(approvedFx);
    expect(store.persistence().quarantined).toBe(0);
    await expect(P.issue(MGR, approvedFx.proposalId, approvedFx.versionId)).rejects.toThrow(
      /proposal-content-hash\/1.*revise the proposal and resubmit/,
    );
    expect(store.table("proposalVersions")[0]!.issue).toBeUndefined();
    await P.revise(PRO, approvedFx.proposalId, "Re-approve under strengthened hashing");
    const ver = await P.submitForReview(PRO, approvedFx.proposalId);
    expect(ver.hashContract).toBe(HASH_CONTRACT);
    await P.approve(REVIEWER, approvedFx.proposalId, ver.id, { acknowledged: ackOf(ver) });
    const issued = await P.issue(MGR, approvedFx.proposalId, ver.id);
    expect(issued.review?.by).toBe(REVIEWER.user.id);
    const old = store.table("proposalVersions").find((x) => x.id === approvedFx.versionId)!;
    expect(old.contentHash).toBe(savedVersion(approvedFx, approvedFx.versionId).contentHash);
    expect("hashContract" in old).toBe(false);
  });
  it("corrupted legacy financials are still quarantined", () => {
    const fx = structuredClone(issuedFx) as Any;
    fx.envelope.tables.proposalVersions[0].document.commercials.summary.totals[0].monthly += 1;
    restore(fx);
    expect(store.persistence().quarantined).toBe(1);
  });
  it("a legacy record with a forged embedded source is quarantined", () => {
    const fx = structuredClone(issuedFx) as Any;
    fx.envelope.tables.proposalVersions[0].document.solution.solutionId = "sol_other";
    restore(fx);
    expect(store.persistence().quarantined).toBe(1);
  });
});

describe("P1-05 current versions use the strengthened contract", () => {
  it("new versions carry /2 and issue normally", async () => {
    const { issued } = await issuedProposal();
    expect(issued.hashContract).toBe(HASH_CONTRACT);
    expect(versionIntegrityProblems(issued)).toEqual([]);
  });
  async function restoreWith(mut: (v: Any) => void) {
    const backend = memoryBackend();
    store.attach(backend);
    const r = await issuedProposal();
    const saved = JSON.parse(backend.read(STORAGE_KEY)!);
    const copy = structuredClone(saved.tables.proposalVersions[0]);
    copy.id = "pv_corrupt";
    mut(copy);
    saved.tables.proposalVersions.push(copy);
    backend.write(STORAGE_KEY, JSON.stringify(saved));
    store.attach(backend);
    return { ...r, backend };
  }
  const cases: [string, (v: Any) => void][] = [
    ["altered embedded solution id", (v) => (v.document.solution.solutionId = "sol_other")],
    [
      "modified requirement with unchanged ids",
      (v) => (v.document.solution.sourceAssessment.requirements[0].statement = "Swapped"),
    ],
    [
      "modified dependency with unchanged ids",
      (v) => v.document.solution.catalog.items[0].dependencies.push("cat_injected"),
    ],
    [
      "modified requirement with the contract marker removed",
      (v) => {
        v.document.solution.sourceAssessment.requirements[0].statement = "Swapped";
        delete v.hashContract;
      },
    ],
    ["unknown contract marker", (v) => (v.hashContract = "proposal-content-hash/1")],
  ];
  for (const [name, mut] of cases)
    it(`quarantines a ${name}; the valid sibling survives`, async () => {
      const { p, issued, backend } = await restoreWith(mut);
      expect(store.persistence()).toMatchObject({ quarantined: 1, backupSaved: true });
      expect((await P.get(PRO, p.id)).versions.map((x) => x.id)).toEqual([issued.id]);
      expect(backend.read(QUARANTINE_KEY)).toContain("pv_corrupt");
    });
  it("an absent marker on unchanged strengthened content is interpreted only as unmarked history", async () => {
    const { p, issued } = await restoreWith((v) => delete v.hashContract);
    expect(store.persistence().quarantined).toBe(0);
    const versions = (await P.get(PRO, p.id)).versions;
    const historical = versions.find((v) => v.id === "pv_corrupt");
    expect(historical).toBeDefined();
    if (!historical) throw new Error("Missing historical version");
    expect(hashContractOf(historical)).toBe(HASH_CONTRACT);
    expect(historical.contentHash).toBe(issued.contentHash);
    expect("hashContract" in historical).toBe(false);
  });
  it("failed quarantine backup keeps the original payload and blocks writes", async () => {
    const m = new Map<string, string>();
    const ctl = { fail: false };
    const backend = {
      kind: "memory" as const,
      read: (k: string) => m.get(k) ?? null,
      write: (k: string, v: string) => {
        if (k === QUARANTINE_KEY && ctl.fail) throw new Error("QuotaExceededError");
        m.set(k, v);
      },
    };
    m.set(STORAGE_KEY, JSON.stringify(issuedFx.envelope));
    store.attach(backend);
    const saved = JSON.parse(m.get(STORAGE_KEY)!);
    saved.tables.proposalVersions[0].document.solution.solutionId = "sol_other";
    const raw = JSON.stringify(saved);
    m.set(STORAGE_KEY, raw);
    ctl.fail = true;
    store.attach(backend);
    expect(store.persistence()).toMatchObject({ protected: true, backupSaved: false });
    expect(m.get(STORAGE_KEY)).toBe(raw);
  });
});
